import {
  Children,
  isValidElement,
  type ReactNode,
} from 'react';
import {
  Platform,
  Pressable,
  StyleSheet,
  TextInput,
  View,
  type ViewProps,
} from 'react-native';
import { ChevronLeft, Search, X } from 'lucide-react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Badge } from '@/components/ui/badge';
import { Text, type TextProps } from '@/components/ui/text';
import { cn, useIconColor, useThemeColor } from '@/lib/utils';

export type AppBarVariant =
  | 'default'
  | 'large'
  | 'search'
  | 'floating'
  | 'glass'
  | 'transparent';

export interface AppBarProps extends ViewProps {
  /** Leading icon / custom element (e.g. back button, avatar). Overrides `onBack`. */
  leading?: ReactNode;
  /** Back button callback. Renders a rounded chevron well when passed. */
  onBack?: () => void;
  /** Trailing action buttons (search, more, settings). */
  trailing?: ReactNode;
  /** Header visual variant. Default: 'default'. */
  variant?: AppBarVariant;
  /** Main header title. */
  title?: string;
  /** Subtitle text displayed beneath main title. */
  subtitle?: string;
  /** Alignment of title in standard mode. Default: 'center'. */
  alignTitle?: 'center' | 'left';
  /** Value for embedded search input when `variant="search"`. */
  searchValue?: string;
  onSearchChange?: (text: string) => void;
  searchPlaceholder?: string;
  /** Auto-apply safe area top inset padding. Default: true. */
  safeArea?: boolean;
  className?: string;
  children?: ReactNode;
}

/**
 * Top-tier mobile App Bar engineered to iOS 18 Human Interface Guidelines.
 * Supports standard centered bar, large collapsible heading, search-integrated bar,
 * and floating island modes.
 */
export function AppBar({
  leading,
  onBack,
  trailing,
  variant = 'default',
  title,
  subtitle,
  alignTitle = 'center',
  searchValue,
  onSearchChange,
  searchPlaceholder = 'Search...',
  safeArea = true,
  className,
  style,
  children,
  ...props
}: AppBarProps) {
  const insets = useSafeAreaInsets();
  const iconColor = useIconColor('foreground');
  const colors = useThemeColor();

  const isLarge = variant === 'large';
  const isSearch = variant === 'search';
  const isFloating = variant === 'floating';
  const isGlass = variant === 'glass';
  const isTransparent = variant === 'transparent';

  const backBtn = onBack ? (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel="Go back"
      onPress={onBack}
      hitSlop={8}
      style={({ pressed }) => [
        styles.circleBtn,
        {
          backgroundColor: pressed ? colors.accent : 'transparent',
        },
      ]}
    >
      <ChevronLeft size={22} color={iconColor} />
    </Pressable>
  ) : null;

  const resolvedLeading = leading ?? backBtn;

  return (
    <View
      className={cn(
        isFloating
          ? 'mx-4 rounded-2xl border border-border bg-card shadow-sm px-3.5 py-2'
          : isGlass
            ? 'border-b border-border/80 bg-card/90 px-3'
            : isTransparent
              ? 'bg-transparent px-3'
              : 'border-b border-border bg-card px-3',
        className
      )}
      style={[
        isFloating
          ? {
              marginTop: safeArea ? insets.top + 8 : 12,
              backgroundColor: colors.card,
              borderColor: colors.border,
            }
          : [
              !isTransparent && { backgroundColor: isGlass ? colors.card : colors.card },
              safeArea && { paddingTop: insets.top + 4 },
              { paddingBottom: isLarge ? 8 : isSearch ? 8 : 8 },
            ],
        style,
      ]}
      {...props}
    >
      {/* Top Navigation Row (52px height) */}
      <View style={styles.topRow}>
        {/* Leading Touch Anchor (Min 44x44px for iOS HIG compliance) */}
        <View style={styles.sideSlot}>{resolvedLeading}</View>

        {/* Center Section: Search Bar OR Standard Title */}
        {isSearch ? (
          <View style={styles.searchBarWrapper}>
            <View
              style={[
                styles.searchBarInner,
                {
                  backgroundColor: colors.muted,
                  borderColor: colors.border,
                },
              ]}
            >
              <Search size={16} color={colors.mutedForeground} />
              <TextInput
                value={searchValue}
                onChangeText={onSearchChange}
                placeholder={searchPlaceholder}
                placeholderTextColor={colors.mutedForeground}
                style={[styles.searchInputText, { color: colors.foreground }]}
                returnKeyType="search"
              />
              {searchValue ? (
                <Pressable
                  onPress={() => onSearchChange?.('')}
                  hitSlop={6}
                  style={styles.clearSearchBtn}
                >
                  <X size={13} color={colors.mutedForeground} />
                </Pressable>
              ) : null}
            </View>
          </View>
        ) : !isLarge ? (
          <View
            style={[
              styles.centerSlot,
              alignTitle === 'left' && styles.leftAlignSlot,
            ]}
          >
            {title ? (
              <View
                style={[
                  styles.titleStack,
                  alignTitle === 'left' && { alignItems: 'flex-start' },
                ]}
              >
                <Text
                  style={[styles.standardTitle, { color: colors.foreground }]}
                  numberOfLines={1}
                >
                  {title}
                </Text>
                {subtitle ? (
                  <Text
                    style={[
                      styles.standardSub,
                      { color: colors.mutedForeground },
                    ]}
                    numberOfLines={1}
                  >
                    {subtitle}
                  </Text>
                ) : null}
              </View>
            ) : (
              children
            )}
          </View>
        ) : (
          <View style={styles.centerSlot}>{!title && children}</View>
        )}

        {/* Trailing Touch Anchor (Min 44x44px) */}
        <View style={[styles.sideSlot, styles.trailingSlot]}>
          {trailing}
        </View>
      </View>

      {/* Large Title Section (iOS Large Display Heading pattern) */}
      {isLarge && (
        <View style={styles.largeTitleSection}>
          {title ? (
            <View style={styles.largeTitleStack}>
              <Text
                style={[styles.largeTitleText, { color: colors.foreground }]}
                numberOfLines={1}
              >
                {title}
              </Text>
              {subtitle ? (
                <Text
                  style={[
                    styles.largeSubText,
                    { color: colors.mutedForeground },
                  ]}
                  numberOfLines={1}
                >
                  {subtitle}
                </Text>
              ) : null}
            </View>
          ) : (
            children
          )}
        </View>
      )}
    </View>
  );
}

export function AppBarTitle({ className, style, ...props }: TextProps) {
  return (
    <Text
      className={cn(
        'text-[17px] font-bold text-foreground text-center tracking-tight',
        className
      )}
      style={style}
      numberOfLines={1}
      {...props}
    />
  );
}

export function AppBarSubtitle({ className, style, ...props }: TextProps) {
  return (
    <Text
      className={cn(
        'text-xs text-muted-foreground text-center mt-0.5',
        className
      )}
      style={style}
      numberOfLines={1}
      {...props}
    />
  );
}

export interface AppBarActionProps {
  className?: string;
  children?: ReactNode;
  badge?: number | string | boolean;
  onPress?: () => void;
  accessibilityLabel?: string;
}

export function AppBarAction({
  className,
  children,
  badge,
  onPress,
  accessibilityLabel,
}: AppBarActionProps) {
  const colors = useThemeColor();

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      hitSlop={6}
      onPress={onPress}
      style={({ pressed }) => [
        styles.circleBtn,
        {
          backgroundColor: pressed ? colors.accent : 'transparent',
        },
      ]}
      className={className}
    >
      {children}
      {badge !== undefined && badge !== false && (
        <View style={styles.badgeWrap}>
          {badge === true ? (
            <View
              style={[
                styles.dotBadge,
                { backgroundColor: colors.destructive },
              ]}
            />
          ) : (
            <Badge
              variant="destructive"
              className="px-1 py-0 min-w-3.5 h-3.5 rounded-full"
            >
              <Text style={styles.badgeText}>{badge}</Text>
            </Badge>
          )}
        </View>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  topRow: {
    height: 50,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    width: '100%',
  },
  sideSlot: {
    minWidth: 42,
    height: 44,
    flexDirection: 'row',
    alignItems: 'center',
  },
  trailingSlot: {
    justifyContent: 'flex-end',
    gap: 4,
  },
  centerSlot: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 6,
  },
  leftAlignSlot: {
    alignItems: 'flex-start',
    paddingHorizontal: 2,
  },
  titleStack: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  standardTitle: {
    fontSize: 17,
    fontWeight: '700',
    letterSpacing: -0.4,
  },
  standardSub: {
    fontSize: 11,
    marginTop: 1,
  },
  circleBtn: {
    position: 'relative',
    width: 40,
    height: 40,
    borderRadius: 20,
    alignItems: 'center',
    justifyContent: 'center',
  },
  searchBarWrapper: {
    flex: 1,
    paddingHorizontal: 6,
  },
  searchBarInner: {
    flexDirection: 'row',
    alignItems: 'center',
    height: 38,
    borderRadius: 12,
    borderWidth: StyleSheet.hairlineWidth,
    paddingHorizontal: 10,
    gap: 8,
  },
  searchInputText: {
    flex: 1,
    fontSize: 14,
    paddingVertical: 0,
    height: '100%',
  },
  clearSearchBtn: {
    padding: 2,
  },
  largeTitleSection: {
    paddingHorizontal: 4,
    paddingTop: 10,
    paddingBottom: 6,
  },
  largeTitleStack: {
    gap: 2,
  },
  largeTitleText: {
    fontSize: 30,
    fontWeight: '800',
    letterSpacing: -0.8,
  },
  largeSubText: {
    fontSize: 13,
  },
  badgeWrap: {
    position: 'absolute',
    top: 4,
    right: 4,
  },
  dotBadge: {
    width: 7,
    height: 7,
    borderRadius: 3.5,
  },
  badgeText: {
    fontSize: 8,
    fontWeight: '800',
    color: '#ffffff',
    lineHeight: 10,
  },
});
